question(non-blocking): Can we make this dict thread safe by using lru_cache? Say something like

```python
import functools
import inspect
from collections.abc import Callable


@functools.lru_cache(maxsize=1024)
def _cached_signature(fn: Callable[..., object], drop_first: bool) -> inspect.Signature:
    sig = inspect.signature(fn)
    if drop_first:
        params = list(sig.parameters.values())[1:]
        sig = sig.replace(parameters=params)
    return sig


def _get_signature(func: Callable[..., object]) -> inspect.Signature:
    # Bound methods are new objects on every attribute access, so key on the
    # underlying function. Only long-lived definitions are cached; per-call
    # closures and callable instances would otherwise be pinned in the cache.
    underlying = getattr(func, "__func__", None)
    if underlying is not None and getattr(func, "__self__", None) is not None:
        return _cached_signature(underlying, True)
    if inspect.isfunction(func) and "<locals>" not in func.__qualname__:
        return _cached_signature(func, False)
    return inspect.signature(func)

Bound methods miss the `<locals>` check applied to functions on line 236, so methods on locally defined classes can still be retained in `_cached_signature`:

```suggestion
        underlying = getattr(func, "__func__", None)
        if (
            underlying is not None
            and getattr(func, "__self__", None) is not None
            and "<locals>" not in getattr(underlying, "__qualname__", "")
        ):
            return _cached_signature(underlying, True)
```
